const game = {
  newMatch(ctx) {
    return {state:{n:9, seat:0}, turn:[ctx.players[0].id]};
  },
  applyMove(state, id, move, ctx) {
    if (!state.n || ctx.players[state.seat].id !== id ||
        !move || typeof move !== "object" || Object.keys(move).length !== 1 ||
        !Number.isInteger(move.take) || move.take < 1 || move.take > state.n) {
      throw new InvalidMove("Choose a legal move on your turn.");
    }
    const n = state.n - move.take;
    if (n > 0) {
      const seat = 1 - state.seat;
      return {state:{n, seat}, turn:[ctx.players[seat].id]};
    }
    const recipient = ctx.players.find(player => player.id === id && player.kind === "human" && player.active !== false)
      || ctx.players.find(player => player.kind === "human" && player.active !== false);
    return {state:{n, seat:state.seat}, turn:null,
      payouts:recipient ? {[recipient.id]:ctx.pot} : {}};
  },
  viewFor(state) { return state; },
  computerMove(state) { return {take:state.n}; },
  randomMove(state, id, ctx) { return {take:1 + Math.floor(ctx.random() * state.n)}; }
};

