const SOURCE_STRINGS = {"title": "Nim", "count": "Stones left: {n}", "take": "Take {n}", "winner": "{name} wins", "wait": "Waiting for the next move", "server_illegal": "Choose a legal move on your turn."};
const baseGameUI = {
  reduce(message) {
    const match = message.type === "ui_event" ? message.state_changed : message;
    const view = match.view || match.state;
    const strings = { ...SOURCE_STRINGS, ...match.strings };
    const translate = (key, values = {}) =>
      strings[key].replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? ""));
    const player = match.players?.[view.seat];
    const name = player?.display_name ?? player?.name ?? view.seat + 1;
    const actingSeat = match.acting_for_player_index;
    const active = view.n > 0 && match.status === "ongoing" && !match.replay &&
      actingSeat === view.seat && match.turn_of_player_indices?.includes(actingSeat);
    const labels = [
      { id: "count", text: translate("count", { n: view.n }), x: 24, y: 24, font_size: 30 },
      { id: "status", text: view.n === 0 ? translate("winner", { name }) :
        active ? String(name) : translate("wait"), x: 24, y: 70, font_size: 22 }
    ];
    const pieces = Array.from({ length: view.n }, (_, index) => ({
      id: "stone_" + index, type: "stone", board: "pile",
      position: { x: 38 + (index % 5) * 83, y: 40 + Math.floor(index / 5) * 80 },
      actions: []
    }));
    const controls = active ? Array.from({ length: view.n }, (_, index) => ({
      id: "take_" + (index + 1), kind: "button", label: translate("take", { n: index + 1 })
    })) : [];
    const result = { scene: { labels, pieces, controls }, local_state: {} };
    if (message.type === "ui_event" && message.event.type === "tap") {
      const index = controls.findIndex(control => control.id === message.event.id);
      if (index >= 0) result.make_move = { take: index + 1 };
    }
    return result;
  }
};

const POLISH_KIND="nim_single_heap";
const POLISH_TITLE="Nim";
const POLISH_STRINGS={"polish_hand": "YOUR HAND", "polish_table": "TABLE", "polish_finished": "ROUND COMPLETE"};

// JIAYI_POLISH_BEGIN
const gameUI = {
 reduce(message, previous) {
  const result=baseGameUI.reduce(message,previous), m=message.type==='ui_event'?message.state_changed:message;
  const v=m.view||m.state||{}, old=result.scene, strings={...SOURCE_STRINGS,...m.strings};
  const kind=POLISH_KIND, nim=kind==='nim_single_heap', snap=kind==='snap'||kind==='slapjack';
  const scene={pieces:[],labels:[],controls:old.controls||[],targets:old.targets||[],paths:old.paths||[]};
  const add=(id,type,x,y,extra={})=>scene.pieces.push({id,type,board:'surface',position:{x,y},actions:[],...extra});
  const label=(id,text,x,y,size=17,color='#f4f2dd')=>scene.labels.push({id,text:String(text),x,y,font_size:size,color});
  const text=k=>strings[k]||POLISH_STRINGS[k]||'';
  add('polish_background','table_art',240,350,{z:-100});
  label('polish_title',strings.title||POLISH_TITLE,26,22,28);
  const status=(old.labels||[]).find(l=>l.id==='status'||l.id==='turn');
  const playing=m.turn_of_player_indices||[v.seat];
  const players=m.players||[],counts=v.counts||[],scores=v.totals||v.miles||v.scores;
  players.forEach((p,i)=>{
   const x=26+(i%3)*147,y=86+Math.floor(i/3)*51;
   add('polish_seat_'+i,playing.includes(i)&&m.status==='ongoing'?'seat_active':'seat_idle',x+67,y+21,{z:-10});
   label('polish_name_'+i,String(p.name||p.display_name||i+1).slice(0,13),x+11,y+7,14,playing.includes(i)?'#f8e3a7':'#d0dfd7');
   const amount=scores?.[i]??counts[i];
   label('polish_score_'+i,amount===undefined?'—':String(amount),x+11,y+25,15,'#ffffff');
  });
  label('polish_status',status?.text||text(m.status==='over'?'polish_finished':'polish_table'),27,407,17,'#e5d5a7');
  const hand=v.hand||[];
  if(!nim&&!snap)label('polish_hand_title',text('polish_hand'),37,452,15,'#a8c9bb');
  if(nim){
   label('polish_stones',String(v.n),208,187,48,'#f3e2b9');
   (old.pieces||[]).forEach((p,i)=>add(p.id,'gem',160+(i%3)*80,265+Math.floor(i/3)*45,{...p,type:'gem',board:'surface',position:{x:160+(i%3)*80,y:265+Math.floor(i/3)*45}}));
   const controls=old.controls||[];scene.controls=[];
   controls.forEach((c,i)=>{
    const x=98+(i%3)*142,y=508+Math.floor(i/3)*65;
    add(c.id,'take_button',x,y,{actions:['tap'],aria_label:c.label,text:c.label});
   });
  }else if(snap){
   const top=kind==='snap'?(v.top||[]):v.top===null||v.top===undefined?[]:[v.top];
   top.forEach((c,i)=>add('polish_public_'+i,'large_card',top.length===1?240:180+i*120,286,{asset:'card_'+c,z:i,rotation:(i?6:-5),animation:{kind:'move',duration_ms:220,key:'pile_'+m.move_count+'_'+i}}));
   if(!top.length)add('polish_deck','large_card',240,286,{asset:'card_back'});
   label('polish_pile',String(v.pileCount||0),229,355,22,'#dbe8ce');
   scene.controls=[];
   (old.controls||[]).forEach((c,i)=>add(c.id,i?'gold_button':'primary_button',240,510+i*86,{actions:['tap'],aria_label:c.label,text:c.label}));
  }else{
   (old.pieces||[]).forEach((p,i)=>{
    const card=hand[i],columns=hand.length>14?9:7,step=columns===9?47:60,row=Math.floor(i/columns),cols=Math.min(columns,hand.length-row*columns),x=240-(cols-1)*step/2+(i%columns)*step,y=529+row*103-(p.selected?12:0);
    scene.pieces.push({...p,type:'hand_card',board:'surface',position:{x,y},asset:'card_'+card,aria_label:p.aria_label||p.text||String(card),text:'',z:20+i,rotation:0,opacity:p.actions?.length||p.selected?1:.78});
   });
   const table=v.table||v.trick?.map(p=>p.card)||((kind==='conquian'&&v.top>=0)?[v.top]:[]);
   const shown=kind==='catch_the_ten'?[v.up,...table].filter(c=>Number.isInteger(c)):table;
   shown.slice(-5).forEach((c,i)=>add('polish_table_'+i,'table_card',240-(Math.min(shown.length,5)-1)*38+i*76,282,{asset:'card_'+c,rotation:(i-(shown.length-1)/2)*4,z:i,animation:{kind:'move',duration_ms:180,key:'trick_'+m.move_count+'_'+i}}));
   if(!shown.length)add('polish_deck','table_card',240,282,{asset:'card_back',opacity:.8});
   if(Number.isInteger(v.trump)&&v.trump>=0)label('polish_trump',['♣','♦','♥','♠'][v.trump],409,204,27,'#e4c480');
  }
  if(m.status==='over'){
   add('polish_result_panel','result_panel',240,281,{z:70});
   label('polish_result',String(status?.text||text('polish_finished')).slice(0,44),55,272,24,'#f6e3ac');
  }
  result.scene=scene;return result;
 }
};
